test:
ledger = EngineFlightLedger()
ledger.record('a', 'eng', 'm', 10, 20)
try:
    ledger.record('b', 'eng', 'm2', 15, 22)
    assert False
except ValueError:
    pass
assert ledger.record('c', 'eng', 'm2', 20, 23) is True
for args in (('eng', 8, 7), ('eng', True, 7)):
    try:
        ledger.engine_flight_time(*args)
        assert False
    except (TypeError, ValueError):
        pass
for call in (lambda: ledger.engine_flight_time('missing'), lambda: ledger.mission_flight_time('missing')):
    try:
        call()
        assert False
    except KeyError:
        pass
